    try{
        // Validate offset bounds
        if (offset < 0 || offset + 1 >= b.length) {
            throw new IndexOutOfBoundsException("offset out of bounds: " + offset);
        }
        // Combine two bytes into a signed short (big‑endian)
        return (short)((b[offset] << 8) | (b[offset + 1] & 0xFF));
    }catch(RuntimeException e){
        throw e;   // propagate unchecked exceptions
    }catch(Exception e){
        // Wrap any unexpected checked exception
        throw new IllegalStateException("Failed to read short at offset " + offset, e);
    }
