private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        return -1;
    }
    int length = headerPart.length();
    if (end < 0) {
        end = 0;
    }
    if (end >= length) {
        return -1;
    }
    for (int i = end; i < length - 1; i++) {
        char current = headerPart.charAt(i);
        if (current == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    // Check for a lone newline at the end (handles "\n" without preceding "\r")
    if (end < length && headerPart.charAt(end) == '\n') {
        return end;
    }
    return -1;
}

