public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    try {
        int lastSeparator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
        int lastDot = path.lastIndexOf('.');
        // no dot found or dot occurs before the last path separator -> no extension
        if (lastDot == -1 || lastDot <= lastSeparator) {
            return null;
        }
        // strip everything from the dot onwards
        return path.substring(0, lastDot);
    } catch (Exception e) {
        // Any unexpected runtime issue will result in null to signal failure
        return null;
    }
}

